// Emitted via JSON.parse to avoid TS2590 on the large baked-HTML literal array.
export const HANDBOOK_SECTIONS: HandbookSection[] = JSON.parse("[{\"id\":\"control\",\"order\":1,\"number\":\"01\",\"eyebrow\":\"START HERE\",\"title\":\"Document control & approval\",\"lead\":\"This handbook replaces the 2022 field-employee handbook only after final legal, HR, operational, and Governing Body approval.\",\"bodyHtml\":\"<aside class=\\\"callout warning\\\"><strong>Controlled draft — not yet effective</strong><div><p>This document is a comprehensive California and home-health handbook draft prepared for counsel and policy-owner review. It must not be distributed for acknowledgment until the release checklist is closed, all contacts and plan choices are confirmed, and the approving authority signs the approval block.</p></div></aside><div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Field</th><th>Draft value</th></tr></thead><tbody><tr><td>Document ID</td><td>CI-HR-HB-2026</td></tr><tr><td>Version</td><td>Draft 1.0</td></tr><tr><td>Prepared</td><td>July 24, 2026</td></tr><tr><td>Proposed effective date</td><td>Pending approval</td></tr><tr><td>Owner</td><td>Human Resources</td></tr><tr><td>Legal review</td><td>Pending California employment counsel</td></tr><tr><td>Operational review</td><td>Pending Administrator / DON / Compliance / Payroll</td></tr><tr><td>Review cycle</td><td>At least annually and upon material legal or operational change</td></tr><tr><td>Supersedes</td><td>Care Indeed Home Health Field Employee Handbook 2022 — upon approval only</td></tr></tbody></table></div><p>Only the approved version in the controlled policy system is authoritative. Printed or downloaded copies may become obsolete. Employees will receive notice of material changes and any required training or acknowledgment.</p>\",\"owner\":\"HR / Compliance / Legal\",\"policyIds\":[\"EN-LC-001\",\"GV-PM-001\",\"GV-PM-002\",\"GV-PM-003\",\"EN-LC-003\"],\"formIds\":[\"EN-FM-001\"],\"externalAuthorities\":[\"CA-WKYR\"],\"employeeAction\":\"\"},{\"id\":\"welcome\",\"order\":2,\"number\":\"02\",\"eyebrow\":\"OUR CULTURE\",\"title\":\"Welcome to Care Indeed\",\"lead\":\"We provide compassionate, professional, patient-centered home health services while protecting employee dignity, safety, and lawful workplace rights.\",\"bodyHtml\":\"<p>Care Indeed Home Health Care, Inc. is built on compassion, authenticity, respect, excellence, accountability, and continuous learning. Every employee contributes to patient safety, service quality, and a workplace in which people can speak up without fear of retaliation.</p><p>This handbook explains the employment standards and employee-facing processes that apply across Care Indeed. Clinical duties, scope, competency, and patient-care procedures are governed by the employee’s approved job description, assignment, Plan of Care, and current clinical policies.</p><aside class=\\\"callout success\\\"><strong>Speak up early</strong><div>Questions are welcome. Employees may contact Human Resources, their supervisor, the Administrator, the Director of Nursing, Compliance, or the confidential reporting channel identified in the employee portal.</div></aside>\",\"owner\":\"Executive Leadership / HR\",\"policyIds\":[\"EN-CM-001\",\"CO-CP-004\",\"GV-OG-001\"],\"formIds\":[],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"contacts\",\"order\":3,\"number\":\"03\",\"eyebrow\":\"CONTACT DIRECTORY\",\"title\":\"Who to contact and how to escalate\",\"lead\":\"Employees must have more than one safe route for employment, clinical, privacy, safety, payroll, and compliance concerns.\",\"bodyHtml\":\"<aside class=\\\"callout warning\\\"><strong>Release blocker</strong><div>Replace every bracketed item below with a verified current contact, URL, hours-of-coverage statement, and after-hours route before approval.</div></aside><div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Need</th><th>Primary route</th><th>Alternate / urgent route</th></tr></thead><tbody><tr><td>Human Resources / leave / accommodation</td><td>[HR phone, email, portal route]</td><td>Any manager or Administrator</td></tr><tr><td>Payroll / time / reimbursement</td><td>[Payroll phone, email, portal route]</td><td>Human Resources</td></tr><tr><td>Compliance / fraud / retaliation</td><td>[Compliance hotline and web route]</td><td>Compliance Officer / external agency</td></tr><tr><td>Privacy / security incident</td><td>[Privacy/Security phone and portal route]</td><td>IT incident route / on-call</td></tr><tr><td>Clinical / patient safety</td><td>Assigned supervisor / RN / DON</td><td>[24/7 clinical on-call number]</td></tr><tr><td>Staffing / missed or late visit</td><td>[24/7 staffing number]</td><td>Clinical on-call / Operations</td></tr><tr><td>Workplace violence / immediate danger</td><td>911, then supervisor/Safety</td><td>[Safety reporting route]</td></tr><tr><td>Work injury / exposure</td><td>911 if emergency; [triage/claims number]</td><td>Supervisor / HR / Employee Health</td></tr><tr><td>Anonymous or confidential concern</td><td>[Anonymous reporting route]</td><td>Compliance / government agency</td></tr></tbody></table></div><p>Employees may bypass a supervisor who is involved in the concern. Emergency services, government agencies, professional boards, labor agencies, and legally protected external reporting remain available.</p><p>Care Indeed provides communication assistance, translation, and an accessible format upon request.</p>\",\"owner\":\"HR / Compliance / Operations\",\"policyIds\":[\"CO-CP-005\",\"CO-CP-006\",\"CO-CP-007\",\"CO-IR-101\",\"OP-SL-002\",\"RM-ER-002\",\"HR-ER-003\"],\"formIds\":[],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"how-to-use\",\"order\":4,\"number\":\"04\",\"eyebrow\":\"SOURCE HIERARCHY\",\"title\":\"How this handbook works\",\"lead\":\"The handbook summarizes employee rights and responsibilities; it does not replace controlling laws, benefit plans, job descriptions, or detailed policies.\",\"bodyHtml\":\"<p>When this handbook and another source differ, the more protective applicable law controls. A benefit plan document controls benefit eligibility and coverage. A collective bargaining agreement controls where applicable. A current approved policy controls operational detail unless it conflicts with law.</p><div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Source</th><th>Purpose</th></tr></thead><tbody><tr><td>This handbook</td><td>Plain-language employee summary and navigation</td></tr><tr><td>Controlled Care Indeed policy</td><td>Detailed rule, procedure, owner, documentation, and audit requirements</td></tr><tr><td>Job description / scope statement</td><td>Role duties, qualifications, supervision, and limits</td></tr><tr><td>Benefit plan / SPD</td><td>Eligibility, coverage, exclusions, claims, and continuation</td></tr><tr><td>Wage notice / offer letter</td><td>Rate, classification, payday, workday/workweek, and employer identity</td></tr><tr><td>Federal, state, and local law</td><td>Minimum rights and obligations; more protective local law may apply</td></tr></tbody></table></div><p>Nothing in this handbook waives any employee right, creates a promise of employment for a fixed period, or authorizes work beyond a person’s license, competency, or assigned scope.</p>\",\"owner\":\"HR / Policy Management\",\"policyIds\":[\"EN-TG-001\",\"EN-TG-002\",\"EN-LC-001\",\"EN-LC-003\",\"HR-TA-006\"],\"formIds\":[],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"at-will\",\"order\":5,\"number\":\"05\",\"eyebrow\":\"EMPLOYMENT RELATIONSHIP\",\"title\":\"At-will employment and no-contract statement\",\"lead\":\"Unless a written agreement signed by an expressly authorized officer states otherwise, employment is at will.\",\"bodyHtml\":\"<p>Either the employee or Care Indeed may end the employment relationship at any time, with or without advance notice and with or without cause, subject to applicable law. No supervisor or manager may make an oral promise of guaranteed employment or alter at-will status.</p><p>The at-will relationship does not permit discrimination, retaliation, wage violations, interference with protected leave, unlawful discipline, or termination for exercising a protected right. Progressive discipline may be used but is not a contractual prerequisite to termination.</p><aside class=\\\"callout info\\\"><strong>Acknowledgment is receipt—not waiver</strong><div>Signing the handbook acknowledgment confirms receipt and understanding. It does not waive statutory rights or convert policy summaries into an employment contract.</div></aside>\",\"owner\":\"HR\",\"policyIds\":[\"HR-ER-002\",\"HR-ER-006\",\"GV-PM-003\"],\"formIds\":[\"EN-FM-001\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"eeo\",\"order\":6,\"number\":\"06\",\"eyebrow\":\"FAIR EMPLOYMENT\",\"title\":\"Equal employment opportunity, accommodations, and respectful work\",\"lead\":\"Care Indeed prohibits discrimination and provides reasonable accommodation through a timely, good-faith interactive process.\",\"bodyHtml\":\"<p>Employment decisions are made without unlawful discrimination based on any characteristic protected by federal, California, or applicable local law, including race, color, ancestry, national origin, citizenship or immigration status where protected, religion, creed, sex, pregnancy, childbirth and related conditions, gender, gender identity or expression, sexual orientation, marital status, age, disability, medical condition, genetic information, reproductive health decision-making, military or veteran status, or any other protected status.</p><p>Applicants and employees may request reasonable accommodation for disability, medical condition, pregnancy-related needs, sincerely held religious belief or practice, or another protected reason. Requests may be oral or written. Care Indeed will engage in the interactive process and will seek only information reasonably necessary to evaluate the request.</p><ul><li>Contact Human Resources or any manager to request accommodation.</li><li>Managers must promptly forward potential accommodation requests to Human Resources.</li><li>Medical information is maintained separately and shared only as permitted or necessary.</li><li>No retaliation is permitted for requesting or using an accommodation.</li></ul><aside class=\\\"callout warning\\\"><strong>Emergency or immediate safety need</strong><div>Tell a supervisor or Human Resources immediately if a temporary change is needed to work safely while the formal process is pending.</div></aside>\",\"owner\":\"HR\",\"policyIds\":[\"HR-ER-004\",\"HR-WM-003\",\"HR-EH-101\",\"HR-TA-001\"],\"formIds\":[\"HR-FM-042\",\"HR-FM-041\"],\"externalAuthorities\":[\"CA-CRD\"],\"employeeAction\":\"\"},{\"id\":\"harassment\",\"order\":7,\"number\":\"07\",\"eyebrow\":\"SAFE & RESPECTFUL WORKPLACE\",\"title\":\"Harassment prevention, complaint channels, and non-retaliation\",\"lead\":\"Harassment, discrimination, bullying tied to a protected status, sexual harassment, and retaliation are prohibited.\",\"bodyHtml\":\"<p>The policy applies to conduct involving employees, applicants, interns, volunteers, contractors, vendors, patients, families, visitors, and third parties in offices, patient homes, vehicles, digital communications, training, work events, and any work-related setting.</p><p>An employee may report concerns to any supervisor or manager, Human Resources, Compliance, the Administrator, the Director of Nursing, or the confidential reporting channel. Employees are not required to report to a person involved in the concern. Managers must report received concerns to Human Resources promptly.</p><ul><li>Reports will be addressed promptly, fairly, and as confidentially as practical. Absolute confidentiality cannot be promised.</li><li>Interim safety or work measures may be used while a concern is reviewed.</li><li>Good-faith reporting, participation in an investigation, requesting accommodation, or opposing unlawful conduct is protected.</li><li>Knowingly false statements may be addressed, but an unsubstantiated good-faith report is not misconduct.</li></ul><aside class=\\\"callout info\\\"><strong>Training</strong><div>Covered employees receive California-compliant harassment-prevention training at the required supervisor or nonsupervisor duration and cadence. A handbook acknowledgment is not a substitute for interactive training.</div></aside>\",\"owner\":\"HR / Compliance\",\"policyIds\":[\"HR-ER-004\",\"HR-ER-003\",\"CO-CP-005\",\"CO-CP-006\",\"CO-CP-007\"],\"formIds\":[\"HR-FM-010\",\"HR-FM-029\",\"HR-FM-046\"],\"externalAuthorities\":[\"CA-HAR\",\"CA-CRD\"],\"employeeAction\":\"\"},{\"id\":\"protected-rights\",\"order\":8,\"number\":\"08\",\"eyebrow\":\"SPEAK-UP RIGHTS\",\"title\":\"Protected reporting, whistleblowing, and concerted activity\",\"lead\":\"Nothing in Care Indeed policy prohibits lawful reporting, wage discussions, protected group activity, agency complaints, or cooperation with government investigations.\",\"bodyHtml\":\"<p>Employees may discuss wages, hours, benefits, staffing, safety, and working conditions; act together for mutual aid or protection; report suspected legal or policy violations; contact a government agency; and cooperate with an investigation, subject to lawful limits on disclosure of patient information and proprietary data.</p><p>Care Indeed prohibits retaliation, intimidation, immigration-related threats, schedule punishment, adverse assignments, surveillance, discipline, or other adverse action because an employee exercised a protected right in good faith.</p><aside class=\\\"callout warning\\\"><strong>Patient privacy still applies</strong><div>Protected workplace activity does not authorize disclosure of patient PHI, passwords, access credentials, or confidential records unrelated to the workplace concern. Employees should use secure reporting channels whenever possible.</div></aside>\",\"owner\":\"Compliance / HR\",\"policyIds\":[\"CO-CP-005\",\"CO-CP-006\",\"CO-CP-007\",\"IT-UP-003\",\"CO-HP-001\"],\"formIds\":[],\"externalAuthorities\":[\"FED-NLRA\",\"CA-WKYR\"],\"employeeAction\":\"\"},{\"id\":\"notices\",\"order\":9,\"number\":\"09\",\"eyebrow\":\"EMPLOYEE NOTICES\",\"title\":\"Required notices, workplace postings, and access to rights information\",\"lead\":\"The handbook supplements—but does not replace—required federal, California, local, safety, wage, leave, and workplace postings and notices.\",\"bodyHtml\":\"<p>Care Indeed maintains required physical postings at covered workplaces and provides electronic or direct distribution where required for remote or field employees. Employees may request the current notice package, applicable wage order, safety plans, paid-sick-leave notice, workers’ compensation information, leave notices, and complaint-agency information from Human Resources.</p><p>Beginning in 2026, Care Indeed provides the annual California Workplace Know Your Rights notice by the applicable February 1 deadline and to new employees as required. Notices are provided in languages normally used to communicate employment information and in accessible formats upon request.</p><ul><li>A missing, outdated, obstructed, or inaccessible posting should be reported to HR or Compliance.</li><li>Electronic delivery supplements rather than replaces a physical posting when the law requires a physical posting.</li><li>No notice or handbook acknowledgment waives the right to contact a government agency.</li><li>Local city or county notices may apply based on the employee’s work location.</li></ul>\",\"owner\":\"HR / Compliance / Safety\",\"policyIds\":[\"EN-CM-001\",\"CO-CP-005\",\"HR-ER-004\",\"HR-WM-003\",\"HR-WM-004\",\"RM-OS-001\"],\"formIds\":[],\"externalAuthorities\":[\"CA-WKYR\",\"CA-PSL\",\"CA-WVPP\",\"CA-LACT\"],\"employeeAction\":\"\"},{\"id\":\"recruitment\",\"order\":10,\"number\":\"10\",\"eyebrow\":\"PRE-HIRE\",\"title\":\"Recruitment, conditional offers, background checks, and Fair Chance\",\"lead\":\"Hiring decisions use job-related criteria, current job descriptions, lawful screening, and documented review.\",\"bodyHtml\":\"<p>Care Indeed provides equal opportunity throughout recruiting and hiring. Applicants are not asked to disclose conviction history before a conditional offer when the California Fair Chance Act applies. After a conditional offer, any criminal-history concern is reviewed through the required individualized assessment and notice process, subject to health-care-specific screening obligations and lawful exceptions.</p><p>Background reports are handled under applicable federal and state consumer-reporting requirements. Applicants receive required notices, authorization requests, pre-adverse-action information, an opportunity to respond, and final notice when applicable.</p><div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Employee-safe portal status</th><th>Meaning</th></tr></thead><tbody><tr><td>Submitted</td><td>Required authorization or information received</td></tr><tr><td>Under review</td><td>HR or authorized vendor is reviewing</td></tr><tr><td>Action required</td><td>Additional lawful information is needed</td></tr><tr><td>Cleared</td><td>Pre-hire gate satisfied</td></tr><tr><td>Review required</td><td>A qualified reviewer must complete a legally required assessment</td></tr><tr><td>Not applicable</td><td>The requirement does not apply to the role</td></tr></tbody></table></div>\",\"owner\":\"HR\",\"policyIds\":[\"HR-TA-001\",\"HR-TA-002\",\"HR-TA-006\"],\"formIds\":[\"HR-FM-003\",\"HR-FM-004\",\"HR-FM-018\",\"HR-FM-031\"],\"externalAuthorities\":[\"CA-FCA\"],\"employeeAction\":\"\"},{\"id\":\"i9\",\"order\":11,\"number\":\"11\",\"eyebrow\":\"PRE-HIRE / DAY 1\",\"title\":\"Work authorization and Form I-9\",\"lead\":\"Employees must complete Form I-9 requirements, but Care Indeed will not demand a particular document or discriminate based on citizenship or immigration status where prohibited.\",\"bodyHtml\":\"<p>The employee completes Section 1 no later than the first day of employment, and Care Indeed completes employer verification within the federal timeline. Employees choose acceptable documents from the authorized lists. Receipts and reverification are handled according to current USCIS rules.</p><p>E-Verify is used only when and to the extent Care Indeed is enrolled or required to use it. Tentative nonconfirmation procedures will follow federal notice and contest requirements. No employee is expected to work before required authorization is established.</p>\",\"owner\":\"HR\",\"policyIds\":[\"HR-TA-001\"],\"formIds\":[],\"externalAuthorities\":[\"FED-I9\",\"CA-WKYR\"],\"employeeAction\":\"\"},{\"id\":\"screening-credentials\",\"order\":12,\"number\":\"12\",\"eyebrow\":\"PRE-HIRE & CONTINUING\",\"title\":\"OIG/SAM screening, licenses, certifications, and eligibility\",\"lead\":\"Care Indeed verifies that workforce members remain eligible, qualified, and properly credentialed for assigned duties.\",\"bodyHtml\":\"<p>Before assignment, Care Indeed verifies applicable licenses, certifications, registries, exclusions, sanctions, and qualifications through authoritative sources. Under agency policy, OIG LEIE and SAM screening is completed before hire or engagement and monthly for active workforce members in scope. Additional checks may occur after name changes, license action, role change, or other triggering event.</p><p>Employees must immediately report any license restriction, expiration, suspension, exclusion, criminal charge or conviction that must lawfully be reported, professional discipline, lapse in required insurance, or other event that may affect eligibility or scope. Reporting does not itself determine the employment outcome; qualified reviewers assess the facts and legal requirements.</p><aside class=\\\"callout danger\\\"><strong>No patient care with an expired or restricted credential</strong><div>Employees may not perform duties requiring a license, certification, registry status, or competency that is expired, restricted, unverified, or outside the employee’s approved scope.</div></aside>\",\"owner\":\"HR / Compliance / DON\",\"policyIds\":[\"HR-TA-003\",\"HR-TA-004\",\"HR-WM-007\",\"CO-CP-001\"],\"formIds\":[\"HR-FM-005\",\"HR-FM-006\"],\"externalAuthorities\":[\"FED-OIG\"],\"employeeAction\":\"\"},{\"id\":\"classification\",\"order\":13,\"number\":\"13\",\"eyebrow\":\"EMPLOYMENT STATUS\",\"title\":\"Employment classification, role, and wage-order coverage\",\"lead\":\"Employees are classified based on actual duties and law—not labels, schedules, or payment method alone.\",\"bodyHtml\":\"<p>Care Indeed will identify each employee’s exempt or nonexempt status, full-time/part-time/per diem status, applicable workday and workweek, wage order, rate of pay, and any applicable local or health-care minimum wage in the employee’s wage notice or offer documentation.</p><p>Part-time, per diem, temporary, probationary, or introductory status does not eliminate statutory rights. Independent contractor status is determined through the legally applicable test and approved process; a 1099, LLC, invoice, or short assignment does not by itself establish contractor status.</p><aside class=\\\"callout info\\\"><strong>Classification questions</strong><div>Employees who believe their classification, wage order, exempt status, or time records are incorrect should contact Payroll or Human Resources without fear of retaliation.</div></aside>\",\"owner\":\"HR / Payroll / Legal\",\"policyIds\":[\"HR-TA-006\",\"HR-WM-001\",\"HR-WM-002\"],\"formIds\":[],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"pay\",\"order\":14,\"number\":\"14\",\"eyebrow\":\"WAGES\",\"title\":\"Pay, wage statements, minimum wage, and final pay\",\"lead\":\"Care Indeed pays all wages when due, provides itemized wage statements, and applies the highest applicable state, local, or covered health-care wage floor.\",\"bodyHtml\":\"<p>Regular paydays and pay periods are identified in the current wage notice and payroll calendar. Employees should promptly review wage statements and report missing hours, rates, premiums, reimbursements, or deductions. No employee will be retaliated against for raising a good-faith pay concern.</p><p>California’s statewide minimum wage is $16.90 per hour as of January 1, 2026. A higher local minimum wage or health-care-worker minimum wage may apply depending on the employee, location, and covered facility. The current applicable rate—not a handbook snapshot—controls.</p><p>Final wages are paid within the time required by California law. Employees discharged by the company are generally owed final wages at termination; employees who resign without at least 72 hours’ notice are generally owed final wages within 72 hours. Accrued vested vacation or PTO is paid at separation where required; statutory paid sick leave is not paid out unless required by a more protective plan or law.</p>\",\"owner\":\"Payroll / HR\",\"policyIds\":[\"HR-WM-001\",\"HR-ER-006\"],\"formIds\":[],\"externalAuthorities\":[\"CA-MW\",\"CA-HCW\",\"CA-PAY\"],\"employeeAction\":\"\"},{\"id\":\"timekeeping\",\"order\":15,\"number\":\"15\",\"eyebrow\":\"WAGES\",\"title\":\"Timekeeping, all hours worked, and off-the-clock work\",\"lead\":\"Nonexempt employees must accurately record all time worked; supervisors may not request, permit, or tolerate off-the-clock work.\",\"bodyHtml\":\"<p>Record the actual start and end of each work period, meal periods where required, training time, required meetings, charting, patient-related calls, required travel between work locations, and other compensable work. Never alter time to match a schedule rather than actual work.</p><ul><li>Do not work before clocking in or after clocking out.</li><li>Do not skip recording charting, calls, texts, training, or required administrative work.</li><li>Report a missed punch or incorrect record promptly; corrections must be truthful and auditable.</li><li>Unapproved overtime may be addressed as a performance matter, but all hours worked will be paid.</li><li>Supervisors must not pressure employees to underreport time or edit time without verification.</li></ul><aside class=\\\"callout info\\\"><strong>Field work</strong><div>Travel between assigned patients or other employer-required locations after the first required work location is generally compensable. Ordinary commuting rules and role-specific wage-order rules remain subject to legal review.</div></aside>\",\"owner\":\"Payroll / Operations\",\"policyIds\":[\"HR-WM-001\",\"OP-SL-001\",\"OP-SL-005\",\"CL-CD-004\"],\"formIds\":[\"HR-FM-019\"],\"externalAuthorities\":[\"CA-OT\",\"CA-WO15\"],\"employeeAction\":\"\"},{\"id\":\"overtime\",\"order\":16,\"number\":\"16\",\"eyebrow\":\"WAGES\",\"title\":\"Overtime, workday, workweek, and schedule controls\",\"lead\":\"Nonexempt employees receive overtime and double time whenever required by the applicable wage order and law.\",\"bodyHtml\":\"<p>California’s general rule requires time-and-one-half after eight hours in a workday, after 40 hours in a workweek, and for the first eight hours on a seventh consecutive workday; double time generally applies after 12 hours in a workday and after eight hours on the seventh consecutive workday. Exceptions and alternative rules may apply to specific classifications.</p><p>A fixed workday and workweek are established by Payroll and may not be manipulated to avoid overtime. An overnight shift is not automatically split in a way that defeats overtime. Employees must obtain advance approval when feasible, but all overtime actually worked must be reported and paid.</p><aside class=\\\"callout warning\\\"><strong>Classification-specific supplement required</strong><div>Home-care, personal-attendant, live-in, clinical-professional, office, and exempt classifications may be governed by different wage orders or exceptions. Before release, counsel must confirm the wage-order matrix for every Care Indeed role and work location.</div></aside>\",\"owner\":\"Payroll / HR / Legal\",\"policyIds\":[\"HR-WM-001\"],\"formIds\":[],\"externalAuthorities\":[\"CA-OT\"],\"employeeAction\":\"\"},{\"id\":\"breaks\",\"order\":17,\"number\":\"17\",\"eyebrow\":\"WAGES & WELL-BEING\",\"title\":\"Meal periods, rest periods, lactation, and heat safety\",\"lead\":\"Field work does not eliminate lawful meal and rest rights.\",\"bodyHtml\":\"<p>Nonexempt employees receive meal periods and paid rest periods under the applicable wage order. The general California rule provides a 30-minute meal period before the end of the fifth hour, a second meal period when required for longer shifts, and paid ten-minute net rest periods for each four hours or major fraction worked. Lawful waivers and on-duty meal agreements require specific conditions and, when required, a revocable written agreement.</p><p>Employees should report missed, late, short, interrupted, or on-duty meal/rest periods using the current payroll process. Care Indeed will investigate and pay any legally required premium. Employees must never falsely record an off-duty meal that was not provided.</p><p>Care Indeed provides lactation break time and a compliant private location, including required seating, surface, electricity, nearby water, and refrigeration. Field employees should contact HR before or during an assignment so a practical arrangement can be made.</p><p>Employees working in heat or other environmental hazards must follow the applicable prevention plan, hydration, rest, communication, and emergency procedures. No employee is expected to remain in an unsafe environment without escalation.</p>\",\"owner\":\"Operations / HR / Safety\",\"policyIds\":[\"HR-WM-001\",\"HR-EH-101\",\"RM-OS-004\",\"RM-SS-001\"],\"formIds\":[],\"externalAuthorities\":[\"CA-MEAL\",\"CA-WO15\",\"CA-LACT\"],\"employeeAction\":\"\"},{\"id\":\"expenses\",\"order\":18,\"number\":\"18\",\"eyebrow\":\"FIELD EMPLOYEE EXPENSES\",\"title\":\"Expense reimbursement, mileage, travel, phones, and supplies\",\"lead\":\"Care Indeed reimburses necessary and reasonable business expenses as required by law and current policy.\",\"bodyHtml\":\"<p>Potential reimbursable expenses include authorized mileage and travel between work locations, parking and tolls, required business use of a personal phone or data plan, approved supplies, required professional fees, and other necessary costs incurred in performing assigned duties.</p><ul><li>Submit expenses through the current approved process with truthful documentation.</li><li>Do not delay reporting because a receipt is unavailable; contact Payroll for an alternate certification process.</li><li>Ordinary commuting is distinguished from employer-required travel based on current law and assignment facts.</li><li>Employees will not be disciplined for requesting lawful reimbursement.</li></ul>\",\"owner\":\"Payroll / Operations\",\"policyIds\":[\"HR-WM-001\",\"OP-SL-003\",\"RM-SS-003\"],\"formIds\":[\"HR-FM-027\"],\"externalAuthorities\":[\"CA-REIMB\"],\"employeeAction\":\"\"},{\"id\":\"attendance\",\"order\":19,\"number\":\"19\",\"eyebrow\":\"SCHEDULING\",\"title\":\"Attendance, call-off, missed shifts, and continuity of care\",\"lead\":\"Employees must communicate absences promptly, while Care Indeed distinguishes unforeseeable illness and protected leave from avoidable attendance misconduct.\",\"bodyHtml\":\"<p>For foreseeable absences, employees should provide as much advance notice as practical. For unexpected illness, emergency, or protected leave, notify the designated staffing or supervisory contact as soon as practical. A rigid 24-hour requirement does not apply to an unforeseeable illness.</p><p>Field staff must not abandon a patient. If relief is delayed or the employee becomes ill on duty, immediately contact the supervisor or on-call service, remain clocked in, follow infection-control and safety instructions, and remain only to the extent safe and necessary until a qualified handoff or emergency response occurs.</p><ul><li>No-call/no-show and repeated avoidable tardiness may lead to corrective action after review.</li><li>Protected sick leave, approved leave, disability accommodation, workers’ compensation, and other legally protected absences are not counted or disciplined unlawfully.</li><li>A missed visit or late arrival must be reported and documented under clinical and scheduling policy.</li></ul>\",\"owner\":\"Operations / Supervisor / HR\",\"policyIds\":[\"HR-WM-001\",\"OP-SL-001\",\"OP-SL-002\",\"CL-SD-024\",\"CL-CP-005\"],\"formIds\":[\"HR-FM-019\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"sick-leave\",\"order\":20,\"number\":\"20\",\"eyebrow\":\"LEAVE & WAGES\",\"title\":\"Paid sick leave\",\"lead\":\"Care Indeed provides paid sick leave that meets or exceeds California and applicable local requirements.\",\"bodyHtml\":\"<p>At minimum, eligible California employees may use no less than 40 hours or five days of paid sick leave per year, whichever provides more time, unless a more protective local law or company plan applies. The current plan’s accrual or frontload method, benefit year, cap, and balance are shown in the wage notice, pay statement, or employee portal.</p><p>Paid sick leave may be used for diagnosis, care, treatment, or preventive care for the employee, a qualifying family member, or a designated person; and for qualifying safe-time purposes. Requests may be oral or written. Care Indeed will not require employees to find a replacement or retaliate for lawful use.</p><p>Foreseeable use should be reported in advance when practical; unforeseeable use should be reported as soon as practical. Medical documentation is not a blanket condition of using statutory paid sick leave, though documentation may be requested when permitted under a different applicable leave law or where there is a legitimate, legally supportable basis.</p><aside class=\\\"callout warning\\\"><strong>Local overlay</strong><div>Bay Area ordinances may provide additional accrual, use, notice, or supplemental-pay rights. The release checklist requires a location-by-location overlay before this handbook becomes effective.</div></aside>\",\"owner\":\"HR / Payroll\",\"policyIds\":[\"HR-WM-003\",\"HR-WM-001\"],\"formIds\":[],\"externalAuthorities\":[\"CA-PSL\"],\"employeeAction\":\"\"},{\"id\":\"leave-overview\",\"order\":21,\"number\":\"21\",\"eyebrow\":\"PROTECTED LEAVE\",\"title\":\"Leave of absence — overview and request process\",\"lead\":\"Care Indeed coordinates overlapping federal, California, local, disability, pregnancy, workers’ compensation, and benefit programs.\",\"bodyHtml\":\"<p>Employees should notify Human Resources when they may need time away for their own health, family care, pregnancy, bonding, bereavement, reproductive loss, military duty, jury/witness service, violence-related needs, organ or bone marrow donation, school activities, voting, or another protected reason. Employees do not need to identify the correct law before requesting help.</p><ol><li>Tell HR or a manager that leave or a schedule change may be needed.</li><li>HR provides required notices and requests only legally permitted information.</li><li>HR determines applicable leaves, wage-replacement programs, benefit continuation, documentation, and expected communication.</li><li>The employee and HR coordinate intermittent leave, return-to-work, accommodation, and access restoration.</li></ol><p>Care Indeed prohibits interference and retaliation. Confidential health information is maintained separately from ordinary personnel files.</p>\",\"owner\":\"HR\",\"policyIds\":[\"HR-WM-003\",\"HR-EH-101\",\"HR-ER-003\"],\"formIds\":[\"HR-FM-040\",\"HR-FM-041\",\"HR-FM-042\"],\"externalAuthorities\":[\"CA-CRD\"],\"employeeAction\":\"\"},{\"id\":\"family-medical\",\"order\":22,\"number\":\"22\",\"eyebrow\":\"PROTECTED LEAVE\",\"title\":\"FMLA, CFRA, Pregnancy Disability Leave, and reasonable accommodation\",\"lead\":\"Federal and California leave rights differ and may run concurrently or consecutively depending on the reason and eligibility.\",\"bodyHtml\":\"<div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Program</th><th>High-level summary</th></tr></thead><tbody><tr><td>FMLA</td><td>For eligible employees of covered employers: up to 12 workweeks for qualifying family/medical reasons and up to 26 workweeks for military caregiver leave.</td></tr><tr><td>CFRA</td><td>For eligible California employees of covered employers: job-protected leave for the employee’s serious health condition, qualifying family care, and bonding; family definitions differ from FMLA.</td></tr><tr><td>Pregnancy Disability Leave</td><td>For employees of employers with five or more employees: up to four months per pregnancy when disabled by pregnancy, childbirth, loss of pregnancy, or related conditions; no 12-month/1,250-hour service prerequisite.</td></tr><tr><td>Reasonable accommodation</td><td>May include schedule changes, modified duties, equipment, transfer, or additional leave, absent undue hardship.</td></tr></tbody></table></div><p>Employees may be entitled to PDL and then CFRA bonding leave, and may also qualify for FMLA, disability accommodation, State Disability Insurance, Paid Family Leave, paid sick leave, or local rights. HR provides individualized designation and notice rather than relying on this summary alone.</p>\",\"owner\":\"HR\",\"policyIds\":[\"HR-WM-003\",\"HR-EH-101\",\"HR-ER-004\"],\"formIds\":[\"HR-FM-040\",\"HR-FM-041\",\"HR-FM-042\",\"HR-FM-044\",\"HR-FM-045\"],\"externalAuthorities\":[\"CA-CRD\"],\"employeeAction\":\"\"},{\"id\":\"di-pfl\",\"order\":23,\"number\":\"23\",\"eyebrow\":\"WAGE REPLACEMENT\",\"title\":\"California Disability Insurance and Paid Family Leave\",\"lead\":\"DI and PFL provide wage replacement; they do not automatically provide job protection.\",\"bodyHtml\":\"<p>Eligible employees may receive California Disability Insurance for a non-work-related disability and Paid Family Leave for qualifying family care, bonding, or military-assistance reasons. As of 2026, PFL generally provides up to eight weeks and replaces approximately 70%–90% of wages depending on income, subject to EDD rules and maximums.</p><p>Care Indeed will not require employees to use sick leave, vacation, or PTO before receiving PFL benefits. Employees may choose to coordinate available paid leave where lawful. HR will explain how wage replacement interacts with FMLA, CFRA, PDL, workers’ compensation, and benefit continuation.</p>\",\"owner\":\"HR / Payroll\",\"policyIds\":[\"HR-WM-003\"],\"formIds\":[\"HR-FM-040\"],\"externalAuthorities\":[\"CA-PFL\"],\"employeeAction\":\"\"},{\"id\":\"other-leaves\",\"order\":24,\"number\":\"24\",\"eyebrow\":\"PROTECTED LEAVE\",\"title\":\"Bereavement, reproductive loss, violence-related, and other protected leave\",\"lead\":\"California and federal law provide additional leave and accommodation rights beyond FMLA and CFRA.\",\"bodyHtml\":\"<ul><li>Bereavement leave for the death of a qualifying family member when applicable.</li><li>Reproductive-loss leave for qualifying events involving assisted reproduction, pregnancy, birth, adoption, or surrogacy.</li><li>Leave and reasonable accommodation for employees or qualifying family members affected by violence, including safety planning, medical care, counseling, relocation, legal proceedings, and related needs.</li><li>Jury duty, subpoenaed witness service, military service, voting, school activities, organ or bone marrow donation, civil air patrol, emergency-responder duties, and other legally protected service.</li></ul><p>Eligibility, duration, documentation, pay, benefit continuation, and notice differ. Contact HR; do not assume an absence is unprotected because it is not named in a schedule or handbook summary.</p>\",\"owner\":\"HR\",\"policyIds\":[\"HR-ER-003\",\"HR-ER-004\",\"HR-WM-003\"],\"formIds\":[\"HR-FM-040\"],\"externalAuthorities\":[\"CA-CRD\"],\"employeeAction\":\"\"},{\"id\":\"benefits\",\"order\":25,\"number\":\"25\",\"eyebrow\":\"BENEFITS\",\"title\":\"Benefits, holidays, retirement, and plan documents\",\"lead\":\"Benefit plan documents and annual enrollment materials—not a stale handbook summary—control eligibility, coverage, claims, and continuation.\",\"bodyHtml\":\"<p>Care Indeed may offer medical, dental, vision, life, retirement, paid time off, holiday, and other benefits according to current plan documents. Eligibility may depend on hours, classification, measurement period, waiting period, or other lawful plan terms.</p><p>The annual holiday schedule, eligibility, and any premium pay are published separately. California law does not generally require paid holidays, but Care Indeed will honor its current written commitments. Employees should not rely on a prior year’s handbook or calendar.</p><p>If a handbook summary conflicts with an SPD, insurance contract, 401(k) plan document, COBRA notice, or other governing plan, the plan document controls to the extent permitted by law.</p>\",\"owner\":\"HR / Benefits / Payroll\",\"policyIds\":[\"HR-WM-001\",\"HR-ER-006\"],\"formIds\":[\"HR-FM-057\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"performance\",\"order\":26,\"number\":\"26\",\"eyebrow\":\"EMPLOYEE JOURNEY\",\"title\":\"30/60/90-day check-ins, performance evaluation, and development\",\"lead\":\"Performance management is a continuing process that distinguishes coaching, competency, formal evaluation, and corrective action.\",\"bodyHtml\":\"<div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Milestone</th><th>Purpose</th></tr></thead><tbody><tr><td>30-day check-in</td><td>Role clarity, onboarding progress, support needs, schedule, safety, and early barriers.</td></tr><tr><td>60-day check-in</td><td>Progress, workload, documentation, competency follow-up, and readiness for the 90-day review when used by the agency.</td></tr><tr><td>90-day introductory evaluation</td><td>Formal review of introductory performance; does not alter at-will status.</td></tr><tr><td>Annual evaluation</td><td>Review of job duties, quality, productivity, conduct, compliance, patient-centered care, goals, and development.</td></tr><tr><td>Triggered review</td><td>Role change, performance concern, competency lapse, incident, accommodation, or return-to-work need.</td></tr></tbody></table></div><p>Employees receive an opportunity to review the evaluation, add comments, and acknowledge receipt. Acknowledgment does not necessarily mean agreement. Clinical competency and independent-practice clearance are separate from performance ratings.</p>\",\"owner\":\"Supervisor / HR / Clinical Leader\",\"policyIds\":[\"HR-ER-001\",\"HR-TA-005\",\"HR-TD-003\"],\"formIds\":[\"HR-FM-008\",\"HR-FM-016\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"discipline\",\"order\":27,\"number\":\"27\",\"eyebrow\":\"ACCOUNTABILITY\",\"title\":\"Coaching, corrective action, discipline, and investigations\",\"lead\":\"Care Indeed uses fair, consistent, fact-based review while preserving at-will employment and immediate safety authority.\",\"bodyHtml\":\"<p>Depending on the circumstances, responses may include coaching, retraining, competency reassessment, counseling, written warning, performance improvement plan, suspension, reassignment, restriction from patient care, or separation. The company may skip steps for serious misconduct, patient-safety risk, credential loss, violence, falsification, theft, abuse, privacy breach, or other material concern.</p><ul><li>Employees receive notice of the concern to the extent appropriate and an opportunity to provide information.</li><li>Investigations are conducted by authorized personnel and documented.</li><li>Interim measures are not presumed discipline and may be used to protect safety or evidence.</li><li>Refusal to sign a corrective-action document is recorded but does not invalidate receipt.</li><li>Retaliation, discriminatory discipline, and inconsistent treatment are prohibited.</li></ul>\",\"owner\":\"Supervisor / HR / Compliance / DON\",\"policyIds\":[\"HR-ER-002\",\"CO-CP-007\",\"HR-TD-003\",\"RM-ER-002\"],\"formIds\":[\"HR-FM-009\",\"HR-FM-032\",\"HR-FM-038\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"complaints\",\"order\":28,\"number\":\"28\",\"eyebrow\":\"REPORTING\",\"title\":\"Employee grievances, complaints, compliance reporting, and non-retaliation\",\"lead\":\"Employees have multiple reporting paths and never need to report through a person involved in the concern.\",\"bodyHtml\":\"<p>Report workplace concerns to a supervisor, Human Resources, the Administrator, the Director of Nursing, Compliance, or the confidential reporting channel. Emergencies and immediate threats should be reported to 911 or appropriate emergency services first.</p><div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Concern</th><th>Primary route</th></tr></thead><tbody><tr><td>Discrimination, harassment, retaliation</td><td>HR or any manager; CRD rights remain available</td></tr><tr><td>Wage, time, break, reimbursement</td><td>Payroll or HR; Labor Commissioner rights remain available</td></tr><tr><td>Patient safety / clinical concern</td><td>Supervisor, RN/DON, on-call, incident process</td></tr><tr><td>Privacy / cybersecurity</td><td>Privacy/Security or IT incident route immediately</td></tr><tr><td>Fraud, billing, kickback, false claim</td><td>Compliance hotline / Compliance Officer</td></tr><tr><td>Workplace violence or hazard</td><td>Supervisor / Safety / emergency response</td></tr><tr><td>Grievance about policy or management</td><td>HR grievance process or Compliance as appropriate</td></tr></tbody></table></div><p>Care Indeed will address concerns promptly and prohibits retaliation for good-faith reporting, participation, or use of an external enforcement agency.</p>\",\"owner\":\"HR / Compliance\",\"policyIds\":[\"HR-ER-003\",\"CO-CP-005\",\"CO-CP-006\",\"CO-CP-007\",\"RM-ER-002\"],\"formIds\":[\"HR-FM-010\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"conduct\",\"order\":29,\"number\":\"29\",\"eyebrow\":\"ETHICS\",\"title\":\"Code of Conduct, conflicts, gifts, referrals, and ethical relationships\",\"lead\":\"Employees must act honestly, avoid conflicts, protect patients, and reject improper remuneration or referral influence.\",\"bodyHtml\":\"<p>Employees may not falsify records, steal, divert medication, mistreat patients, accept or offer improper gifts or benefits, misuse confidential information, submit false claims, alter time records, retaliate, or use their position for personal gain.</p><p>Potential conflicts—including outside employment, financial interests, family relationships, gifts, patient/vendor relationships, referral arrangements, or use of company opportunities—must be disclosed for review. A dollar threshold alone does not determine whether a gift is appropriate; patient vulnerability, referral risk, appearance of influence, policy, and law matter.</p><aside class=\\\"callout danger\\\"><strong>Patient and referral boundaries</strong><div>Never solicit patients for private work, accept payment outside approved billing, steer referrals for personal benefit, borrow from patients, become a patient’s fiduciary, or accept a bequest without advance legal/compliance review.</div></aside>\",\"owner\":\"Compliance / HR\",\"policyIds\":[\"CO-CP-004\",\"GV-GB-003\",\"CO-FA-001\",\"CO-FA-002\",\"CO-FA-003\"],\"formIds\":[\"GV-FM-006\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"substance\",\"order\":30,\"number\":\"30\",\"eyebrow\":\"FITNESS FOR DUTY\",\"title\":\"Drug-free workplace, cannabis, alcohol, medication, smoking, and fitness for duty\",\"lead\":\"Care Indeed prohibits on-duty impairment and unsafe substance use while respecting lawful off-duty conduct and accommodation rights.\",\"bodyHtml\":\"<p>Employees may not possess, use, sell, transfer, or be impaired by alcohol, cannabis, illegal drugs, or misused medication while working, driving for work, on Care Indeed property, in a patient home, or while responsible for patient care. Smoking and vaping are prohibited where required by law, patient preference, assignment rules, or Care Indeed policy.</p><p>California generally protects lawful off-duty cannabis use and prohibits employment decisions based solely on a test showing nonpsychoactive cannabis metabolites, subject to statutory exceptions and federal requirements. Care Indeed may prohibit use, possession, or impairment at work and may use lawful testing methods under a reviewed policy.</p><ul><li>Pre-employment, reasonable-suspicion, post-incident, return-to-duty, or other testing occurs only when authorized by current law and policy.</li><li>A post-incident test is not automatic merely because an incident occurred; the facts, safety concern, lawful basis, and testing method are reviewed.</li><li>Employees must not work while medication, illness, fatigue, alcohol, cannabis, or another substance makes work unsafe.</li><li>Employees do not need to disclose a diagnosis or medication list to a supervisor; contact HR or Employee Health when accommodation, restriction, or fitness review may be needed.</li><li>Reasonable-suspicion observations are documented by trained personnel, and test information is handled confidentially.</li></ul><aside class=\\\"callout warning\\\"><strong>Safety-sensitive and federal exceptions</strong><div>Federal contracts, federal funding conditions, required background investigations, professional licensing, or safety-sensitive duties may create additional rules. Counsel must confirm the role-by-role testing matrix before release.</div></aside>\",\"owner\":\"HR / Employee Health / Safety / Legal\",\"policyIds\":[\"HR-ER-005\",\"HR-EH-101\",\"HR-ER-004\",\"RM-OS-101\",\"RM-SS-003\"],\"formIds\":[\"HR-FM-001\",\"HR-FM-002\",\"HR-FM-044\"],\"externalAuthorities\":[\"CA-CAN\"],\"employeeAction\":\"\"},{\"id\":\"privacy\",\"order\":31,\"number\":\"31\",\"eyebrow\":\"PRIVACY\",\"title\":\"HIPAA, CMIA, confidentiality, and minimum necessary\",\"lead\":\"Patient information is accessed, used, and disclosed only for authorized work and only to the minimum extent necessary.\",\"bodyHtml\":\"<p>Protected health information and other sensitive data must remain within approved systems and workflows. Access is role-based and audited. Employees may not browse records out of curiosity, use shared credentials, photograph patient information, store PHI in personal notes, or discuss patients in public or with unauthorized people.</p><ul><li>Verify identity and authority before sharing information.</li><li>Use approved secure messaging and EHR tools.</li><li>Keep screens, papers, and conversations private in homes, vehicles, and public spaces.</li><li>Report misdirected messages, lost devices, unauthorized access, suspicious email, or any suspected privacy/security incident immediately.</li><li>Dispose of paper and media only through approved secure methods.</li></ul><p>California CMIA and other state confidentiality requirements may be more protective than HIPAA and are incorporated into Care Indeed policy.</p>\",\"owner\":\"Privacy / Security / Compliance\",\"policyIds\":[\"CO-HP-001\",\"CO-HP-002\",\"CO-HP-003\",\"CO-HP-004\",\"CO-HP-101\",\"CO-CA-001\",\"CO-IR-101\",\"IT-SC-006\"],\"formIds\":[\"HR-FM-037\",\"IT-FM-009\"],\"externalAuthorities\":[\"FED-HIPAA\"],\"employeeAction\":\"\"},{\"id\":\"technology\",\"order\":32,\"number\":\"32\",\"eyebrow\":\"DIGITAL CONDUCT\",\"title\":\"Technology, mobile devices, email, social media, and AI\",\"lead\":\"Use only approved tools for Care Indeed work and patient information.\",\"bodyHtml\":\"<p>Company systems are provided for authorized business use and may be monitored as permitted by law. Employees have no expectation of privacy in company systems beyond rights provided by law. Monitoring must be disclosed and conducted for legitimate purposes.</p><ul><li>Use unique credentials and MFA; never share passwords or approve an unexpected prompt.</li><li>Do not place PHI in consumer text, personal email, unapproved cloud storage, social media, or unapproved AI tools.</li><li>Keep devices encrypted, locked, updated, and physically secure.</li><li>Report loss, theft, phishing, malware, or suspected access immediately.</li><li>Only authorized spokespeople may make official public statements.</li><li>Social-media rules do not prohibit lawful wage discussions, protected concerted activity, whistleblowing, or government reporting.</li></ul><p>AI or automated tools may be used only when approved, with permitted data, required human review, and no expansion of clinical scope. Do not enter PHI, employee confidential data, credentials, or proprietary records into an unapproved AI service.</p>\",\"owner\":\"IT / Security / Privacy\",\"policyIds\":[\"IT-UP-001\",\"IT-UP-002\",\"IT-UP-003\",\"IT-UP-004\",\"IT-SC-001\",\"IT-SC-002\",\"IT-SC-006\",\"CO-AI-101\"],\"formIds\":[\"IT-FM-001\",\"IT-FM-009\",\"HR-FM-028\"],\"externalAuthorities\":[\"FED-NLRA\"],\"employeeAction\":\"\"},{\"id\":\"employee-privacy\",\"order\":33,\"number\":\"33\",\"eyebrow\":\"EMPLOYEE DATA\",\"title\":\"Employee privacy, monitoring, and personnel records\",\"lead\":\"Care Indeed limits access to employee information and provides legally required notice and access rights.\",\"bodyHtml\":\"<p>Personnel, medical, accommodation, background, investigation, payroll, and credential records are maintained with access appropriate to the record type. Medical and legally restricted records are kept separate where required.</p><p>Current and former employees may request inspection or copies of personnel records relating to performance or grievances under California law. Care Indeed will respond within the required timeframe and may charge no more than the actual reproduction or lawful mailing cost.</p><p>Where the California Consumer Privacy Act applies, Care Indeed provides applicable employee/applicant privacy notices describing categories collected, purposes, disclosures, retention, and rights. Monitoring of email, devices, vehicles, locations, or video is conducted only as disclosed and permitted.</p>\",\"owner\":\"HR / Privacy\",\"policyIds\":[\"HR-WM-005\",\"HR-WM-007\",\"CO-HP-007\",\"CO-HP-101\",\"IT-DR-003\"],\"formIds\":[\"HR-FM-015\"],\"externalAuthorities\":[\"CA-PERS\"],\"employeeAction\":\"\"},{\"id\":\"safety\",\"order\":34,\"number\":\"34\",\"eyebrow\":\"SAFETY\",\"title\":\"IIPP, workplace violence prevention, emergency preparedness, and hazard reporting\",\"lead\":\"Every employee has the right and responsibility to work safely, report hazards, and participate in safety improvement without retaliation.\",\"bodyHtml\":\"<p>Care Indeed maintains an Injury and Illness Prevention Program, workplace-violence prevention controls, emergency preparedness program, and other written safety plans applicable to office, field, vehicle, and patient-home work.</p><ul><li>Review assignment hazards before work begins.</li><li>Use required PPE, equipment, safe lifting, infection-control, and communication procedures.</li><li>Report hazards, threats, violent incidents, near misses, injuries, unsafe homes, environmental risks, or defective equipment promptly.</li><li>Call 911 for immediate danger; leave or avoid an unsafe location when necessary and notify the supervisor.</li><li>Participate in required training, drills, incident review, and corrective actions.</li></ul><p>Employees may obtain access to the applicable IIPP and workplace-violence plan. Reports are accepted without retaliation and may be made through alternative channels if a supervisor is involved.</p>\",\"owner\":\"Safety / Administrator / Operations\",\"policyIds\":[\"RM-OS-001\",\"RM-OS-101\",\"RM-SS-001\",\"RM-SS-002\",\"RM-EP-001\",\"RM-EP-002\",\"OP-FM-005\"],\"formIds\":[\"RM-FM-001\",\"RM-FM-004\",\"RM-FM-005\",\"RM-FM-009\",\"RM-FM-013\",\"RM-FM-014\",\"HR-FM-030\"],\"externalAuthorities\":[\"CA-WVPP\",\"CA-IIPP\",\"FED-EP\"],\"employeeAction\":\"\"},{\"id\":\"exposure\",\"order\":35,\"number\":\"35\",\"eyebrow\":\"OCCUPATIONAL HEALTH\",\"title\":\"Bloodborne pathogens, aerosol-transmissible disease, infection prevention, and exposure response\",\"lead\":\"Employees receive risk-based training, PPE, vaccination offers, exposure response, and medical follow-up at no cost where required.\",\"bodyHtml\":\"<p>Employees with occupational exposure receive initial and recurring bloodborne-pathogen training, access to the Exposure Control Plan, and the Hepatitis B vaccine offer within the required timeframe after training and assignment. Employees who decline sign the prescribed declination and may later accept the vaccine.</p><p>After a needlestick, splash, respiratory exposure, or other occupational incident: perform immediate first aid, notify the supervisor or designated response line, obtain prompt medical evaluation, preserve source information as permitted, and complete the required incident documentation. Post-exposure evaluation and follow-up are confidential.</p><ul><li>Follow standard precautions and transmission-based precautions as assigned.</li><li>Use approved sharps and never recap unless a specific approved procedure requires it.</li><li>Perform hand hygiene before and after patient contact and PPE use.</li><li>Do not work while impaired by illness or exposure restrictions; contact Employee Health/HR.</li><li>Complete annual or otherwise required health screening, TB assessment, and fit testing based on role and current rules.</li></ul>\",\"owner\":\"Employee Health / Safety / DON\",\"policyIds\":[\"RM-OS-002\",\"RM-OS-003\",\"RM-OS-101\",\"CL-SD-016\",\"HR-EH-101\",\"HR-WM-003\",\"HR-WM-004\"],\"formIds\":[\"HR-FM-012\",\"HR-FM-013\",\"HR-FM-014\",\"HR-FM-021\",\"HR-FM-023\"],\"externalAuthorities\":[\"FED-BBP\"],\"employeeAction\":\"\"},{\"id\":\"injury\",\"order\":36,\"number\":\"36\",\"eyebrow\":\"INJURY RESPONSE\",\"title\":\"Work-related injury, workers’ compensation, and incident reporting\",\"lead\":\"Report work-related injuries and illnesses immediately; emergency care comes first.\",\"bodyHtml\":\"<p>For an emergency, call 911. Otherwise, notify the supervisor and use the current workers’ compensation or triage process. Care Indeed provides required claim information and does not retaliate for reporting an injury or filing a claim.</p><p>Incident reporting is broader than physical injury. Report patient falls, medication errors, exposure incidents, privacy/security events, missed visits, equipment failures, vehicle collisions, threats, near misses, complaints, abuse concerns, and other events defined by policy.</p><p>Workers’ compensation wage and medical benefits may coordinate with FMLA, CFRA, accommodation, paid sick leave, or other programs. HR manages coordination and return-to-work; employees should not be required to use leave in a way prohibited by law.</p>\",\"owner\":\"Safety / HR / Claims\",\"policyIds\":[\"HR-WM-004\",\"RM-ER-002\",\"RM-ER-006\",\"HR-EH-101\",\"QA-AE-004\"],\"formIds\":[\"HR-FM-014\",\"HR-FM-023\",\"HR-FM-052\"],\"externalAuthorities\":[\"CA-WKYR\"],\"employeeAction\":\"\"},{\"id\":\"field-safety\",\"order\":37,\"number\":\"37\",\"eyebrow\":\"FIELD WORK\",\"title\":\"Home-visit safety, driving, transportation, and hazardous conditions\",\"lead\":\"Field employees must protect themselves and patients before, during, and after every visit.\",\"bodyHtml\":\"<ul><li>Review address, known hazards, communication plan, and required supplies before travel.</li><li>Use seat belts, obey traffic law, never text while driving, and do not drive impaired or dangerously fatigued.</li><li>Secure patient records, devices, medications, and supplies out of view and against theft or temperature damage.</li><li>Park in a safe location, remain aware of animals, weapons, smoke, violence, environmental hazards, and unsafe persons.</li><li>Do not enter or remain in an unsafe home; move to safety and contact the supervisor or emergency services.</li><li>Follow inclement-weather, heat, wildfire, air-quality, and emergency instructions.</li><li>Report vehicle accidents and unsafe conditions immediately.</li></ul><p>Employees using a personal vehicle for work must maintain required license, insurance, registration, and safe operating condition. Expiration or restriction must be reported before the next driving assignment.</p>\",\"owner\":\"Operations / Safety\",\"policyIds\":[\"RM-SS-001\",\"RM-SS-002\",\"RM-SS-003\",\"OP-SL-003\",\"OP-SL-007\",\"RM-OS-004\"],\"formIds\":[],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"patient-rights\",\"order\":38,\"number\":\"38\",\"eyebrow\":\"PATIENT PROTECTION\",\"title\":\"Patient rights, abuse/neglect reporting, boundaries, and professional conduct\",\"lead\":\"Every patient must be treated with dignity, privacy, respect, choice, safety, and freedom from abuse, neglect, exploitation, discrimination, retaliation, restraint, and seclusion.\",\"bodyHtml\":\"<p>Employees must report suspected abuse, neglect, exploitation, self-neglect, injury of unknown source, misappropriation, or unsafe restraint through the required external and internal channels. Internal reporting does not replace a mandated external report.</p><p>Employees must maintain professional boundaries. Do not borrow or lend money, accept significant gifts, become a patient’s fiduciary, witness legal documents outside approved policy, solicit private work, engage in personal or sexual relationships, use patient property, or conduct personal business during paid care time.</p><aside class=\\\"callout danger\\\"><strong>Immediate reporting</strong><div>When abuse or immediate danger is suspected, protect safety, call emergency services or the required reporting authority as appropriate, notify Care Indeed, and complete the required written report within the legal/policy timeframe.</div></aside>\",\"owner\":\"All Staff / DON / Compliance\",\"policyIds\":[\"CL-PR-001\",\"CL-PR-004\",\"CL-PR-006\",\"HR-ER-009\",\"CO-CP-004\"],\"formIds\":[\"HR-FM-033\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"clinical-scope\",\"order\":39,\"number\":\"39\",\"eyebrow\":\"CLINICAL PRACTICE\",\"title\":\"Job descriptions, clinical scope, orders, Plan of Care, and documentation\",\"lead\":\"No employee may perform a task merely because it appears in training; the task must be permitted by license, competency, job description, assignment, and Plan of Care.\",\"bodyHtml\":\"<p>Clinical staff follow authenticated orders, the current Plan of Care, discipline-specific standards, and supervisory direction. Changes in condition, missed care, medication concerns, orders, frequencies, and safety risks must be escalated promptly.</p><ul><li>Document contemporaneously, accurately, and completely in the approved record.</li><li>Never backdate, falsify, copy forward without verification, or chart care not personally provided.</li><li>Late entries, corrections, and amendments must follow the approved method and preserve the audit trail.</li><li>Do not create shadow records, personal patient notebooks, or unapproved worksheets containing PHI.</li><li>Report when workload, technology, or assignment conditions make timely documentation or safe care impossible.</li></ul>\",\"owner\":\"DON / Discipline Supervisor\",\"policyIds\":[\"HR-TA-006\",\"CL-CD-001\",\"CL-CD-002\",\"CL-CD-003\",\"CL-CD-004\",\"CL-DC-101\",\"CL-CP-001\",\"CL-CP-003\",\"CL-CP-005\"],\"formIds\":[\"HR-FM-031\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"visits\",\"order\":40,\"number\":\"40\",\"eyebrow\":\"CARE DELIVERY\",\"title\":\"Scheduling, missed visits, after-hours communication, and continuity\",\"lead\":\"Employees must follow assigned frequency, report barriers before a visit is missed, and never independently change the Plan of Care.\",\"bodyHtml\":\"<p>Use the approved scheduling and communication system. Notify the office promptly of lateness, refusal, hospitalization, unsafe conditions, inability to reach the patient, or any event that may cause a missed or shortened visit. Follow the escalation process and document the outcome.</p><p>Employees may not reschedule, skip, add, or change ordered care outside the approved authority. After-hours or on-call concerns are directed through the designated channel. Patient abandonment and unsafe handoff are prohibited.</p>\",\"owner\":\"Operations / Clinical Supervisor\",\"policyIds\":[\"OP-SL-001\",\"OP-SL-002\",\"OP-SL-005\",\"CL-SD-024\",\"CL-SD-025\",\"CL-CP-003\",\"CL-CP-005\"],\"formIds\":[],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"hha\",\"order\":41,\"number\":\"41\",\"eyebrow\":\"HHA SUPPLEMENT\",\"title\":\"Home Health Aide requirements, in-service education, competency, and supervision\",\"lead\":\"HHA assignments have specific federal and agency requirements that are distinct from general annual training.\",\"bodyHtml\":\"<div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Requirement</th><th>Current rule / Care Indeed expectation</th></tr></thead><tbody><tr><td>Qualification and competency</td><td>HHA must meet training/competency requirements and may not perform a task rated unsatisfactory without direct RN supervision until retraining and successful reevaluation.</td></tr><tr><td>In-service education</td><td>At least 12 hours during each 12-month period.</td></tr><tr><td>Patient receiving skilled services</td><td>RN or other appropriate skilled professional completes a supervisory assessment no less frequently than every 14 days; one limited virtual assessment may be permitted per 60-day episode under the federal rule.</td></tr><tr><td>Annual direct observation — skilled patient</td><td>An appropriate skilled professional makes an annual on-site visit to observe each aide performing care.</td></tr><tr><td>Aide-only patient</td><td>RN makes an on-site assessment every 60 days.</td></tr><tr><td>Semiannual direct observation — aide-only</td><td>RN observes and assesses each aide performing care at least semiannually.</td></tr><tr><td>Verified deficiency</td><td>Care Indeed provides retraining and competency evaluation for the deficient and related skills.</td></tr></tbody></table></div><p>The aide follows the written patient-care instructions, reports changes, completes required records, complies with infection control, honors patient rights, and performs only assigned tasks. The HHA does not independently assess, diagnose, modify the Plan of Care, or perform licensed-nurse duties.</p>\",\"owner\":\"RN / DON / HHA\",\"policyIds\":[\"CL-SD-006\",\"CL-SD-007\",\"CL-SD-008\",\"HR-TD-003\",\"HR-TD-001\",\"HR-JD-007\"],\"formIds\":[\"HR-FM-016\",\"HR-FM-017\",\"HR-FM-038\"],\"externalAuthorities\":[\"FED-HHA\"],\"employeeAction\":\"\"},{\"id\":\"discipline-supervision\",\"order\":42,\"number\":\"42\",\"eyebrow\":\"ROLE SUPPLEMENTS\",\"title\":\"Clinical supervision by discipline\",\"lead\":\"Supervision and competency are role- and assignment-specific; this handbook does not create one universal monthly visit.\",\"bodyHtml\":\"<div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Role</th><th>Employee-facing expectations</th></tr></thead><tbody><tr><td>RN</td><td>Initial and ongoing competency; documentation and clinical-review obligations; supervision or leadership duties when assigned.</td></tr><tr><td>LVN</td><td>Practices under authorized RN/physician direction within California scope; no independent initial comprehensive assessment or OASIS authorization unless law and policy expressly permit.</td></tr><tr><td>PTA</td><td>Receives PT supervision, reassessment, communication, and documentation review at the cadence required by current policy and law.</td></tr><tr><td>COTA</td><td>Receives OT supervision, reassessment, communication, and documentation review at the cadence required by current policy and law.</td></tr><tr><td>PT / OT / SLP / MSW</td><td>Initial supervised practice, discipline-specific competency, record review, and ongoing review as assigned.</td></tr><tr><td>DON / Administrator</td><td>Leadership, oversight, compliance, and advanced-training requirements; administrative assignment does not expand clinical scope.</td></tr></tbody></table></div><p>The employee portal should display the exact applicable supervisor, cadence, due date, evidence, and clearance impact. If the controlling source provides only a triggered or state-law cadence, the portal must not invent a number.</p>\",\"owner\":\"DON / Discipline Supervisors\",\"policyIds\":[\"CL-SD-001\",\"CL-SD-002\",\"CL-SD-003\",\"CL-SD-004\",\"CL-SD-005\",\"CL-SD-008\",\"HR-TD-003\",\"HR-TA-006\"],\"formIds\":[\"HR-FM-016\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"training\",\"order\":43,\"number\":\"43\",\"eyebrow\":\"LEARNING\",\"title\":\"Orientation, policy learning, annual/recurring training, competency, and acknowledgment\",\"lead\":\"Training, policy reading, competency, supervised practice, drills, and clearance are separate requirements.\",\"bodyHtml\":\"<p>Employees complete assigned General Agency Orientation, role-specific modules, policy readings, quizzes, attestations, live sessions, drills, competency checkoffs, supervised visits, and remediation. Completion of online content alone does not authorize independent clinical practice.</p><div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Requirement type</th><th>What proves completion</th></tr></thead><tbody><tr><td>Online module</td><td>Canonical module/version, required lessons, assessment result, and completion event.</td></tr><tr><td>Policy learning</td><td>Exact policy version/hash, required reading, approved quiz when assigned, and acknowledgment.</td></tr><tr><td>Competency</td><td>Authorized evaluator, method, skill/result, date, and sign-off.</td></tr><tr><td>Supervised visit</td><td>Assignment, supervisor, patient-safe context, observation/assessment, and outcome.</td></tr><tr><td>Drill/live activity</td><td>Attendance, participation, scenario/exercise, and after-action record where required.</td></tr><tr><td>Clearance</td><td>All role gates satisfied and authorized reviewer decision.</td></tr></tbody></table></div><p>California harassment training is generally biennial for covered employers, not universally annual. Emergency-preparedness training and testing follow 42 CFR § 484.102. Bloodborne-pathogen training is annual for occupationally exposed staff. HHA in-service hours are tracked separately. Care Indeed assigns additional role- and policy-specific education when required.</p>\",\"owner\":\"HR / DON / Compliance\",\"policyIds\":[\"HR-TA-005\",\"HR-TD-001\",\"HR-TD-002\",\"HR-TD-003\",\"HR-TD-005\",\"HR-TR-101\",\"CO-CP-008\",\"GV-PM-003\",\"EN-LC-003\"],\"formIds\":[\"HR-FM-007\",\"HR-FM-016\",\"HR-FM-017\",\"HR-FM-024\",\"HR-FM-030\",\"EN-FM-001\"],\"externalAuthorities\":[\"CA-HAR\",\"FED-EP\",\"FED-BBP\",\"FED-HHA\"],\"employeeAction\":\"\"},{\"id\":\"renewals\",\"order\":44,\"number\":\"44\",\"eyebrow\":\"EMPLOYEE JOURNEY\",\"title\":\"Credential, health-clearance, and document renewal\",\"lead\":\"Employees must keep required credentials and documents current and respond to renewal reminders before expiration.\",\"bodyHtml\":\"<p>The employee portal may track professional license, HHA certificate/registry, CPR/BLS, specialty credentials, driver’s license, auto insurance, TB assessment, immunization/health clearance, fit testing, training certificates, and other role-specific records.</p><p>An uploaded document is not accepted until reviewed and verified by the responsible owner. Care Indeed may suspend the affected duty or assignment while a required credential is expired, restricted, or under review. Employees receive notice and an opportunity to correct errors where appropriate.</p>\",\"owner\":\"HR / Employee Health / DON\",\"policyIds\":[\"HR-TA-004\",\"HR-WM-003\",\"HR-EH-101\",\"RM-SS-003\"],\"formIds\":[\"HR-FM-006\",\"HR-FM-012\",\"HR-FM-021\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"appearance-boundaries\",\"order\":45,\"number\":\"45\",\"eyebrow\":\"PROFESSIONAL STANDARDS\",\"title\":\"Professional appearance, boundaries, media, and respectful conduct\",\"lead\":\"Appearance and conduct standards must be job-related, safe, respectful, inclusive, and reasonably accommodating.\",\"bodyHtml\":\"<p>Employees wear clean, safe, role-appropriate attire and identification, follow infection-control and PPE requirements, maintain hygiene appropriate to patient care, and avoid fragrances when requested or when patient sensitivity is known. Dress standards are applied without unlawful sex or cultural stereotyping and are reasonably accommodated for disability, pregnancy, religion, gender identity/expression, and other protected needs.</p><p>Only authorized representatives speak for Care Indeed to the media. Employees retain protected rights to discuss working conditions, contact government agencies, and engage in lawful concerted activity, while continuing to protect patient information and confidential records.</p>\",\"owner\":\"HR / Operations / Communications\",\"policyIds\":[\"CO-CP-004\",\"GV-EA-002\",\"IT-UP-003\",\"HR-ER-004\"],\"formIds\":[],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"leave-return\",\"order\":46,\"number\":\"46\",\"eyebrow\":\"RETURN JOURNEY\",\"title\":\"Leave, return to work, accommodation, and access restoration\",\"lead\":\"Return-to-work planning protects health, privacy, and safe role performance.\",\"bodyHtml\":\"<p>Before return, HR determines whether legally permitted documentation is required, whether restrictions or accommodation apply, and whether credentials, training, system access, patient assignments, or competency must be refreshed. Medical diagnosis is not displayed in ordinary employee or supervisor dashboards.</p><ul><li>HR confirms return date and restrictions.</li><li>Supervisor and HR identify temporary or ongoing accommodation.</li><li>IT restores access only after authorization.</li><li>Clinical leadership determines competency or supervised-practice needs.</li><li>Employee receives policy/training updates missed during leave.</li></ul>\",\"owner\":\"HR / Supervisor / IT / DON\",\"policyIds\":[\"HR-EH-101\",\"HR-WM-003\",\"HR-ER-004\",\"IT-SC-002\",\"HR-TD-003\"],\"formIds\":[\"HR-FM-041\",\"HR-FM-042\",\"HR-FM-044\",\"HR-FM-045\",\"IT-FM-001\"],\"externalAuthorities\":[],\"employeeAction\":\"\"},{\"id\":\"separation\",\"order\":47,\"number\":\"47\",\"eyebrow\":\"END OF EMPLOYMENT\",\"title\":\"Separation, final pay, benefits, records, and offboarding\",\"lead\":\"Offboarding protects the employee, patients, company assets, confidential information, and legal recordkeeping.\",\"bodyHtml\":\"<p>Employees are encouraged, but generally not required, to provide advance resignation notice. Care Indeed will process final wages, benefit notices, equipment return, access revocation, patient handoff, records preservation, and required government reporting within applicable timelines.</p><ul><li>Return badges, devices, keys, records, supplies, and other property.</li><li>Do not delete or retain Care Indeed or patient records.</li><li>Complete final time and expense submissions.</li><li>Update contact information for tax and benefit notices.</li><li>Receive benefit continuation and retirement information where applicable.</li><li>Request training transcript, certificates, or personnel records through the current process.</li></ul><p>Final pay will not be unlawfully withheld because property is outstanding; Care Indeed may use lawful recovery methods. Continuing confidentiality and patient-privacy obligations remain after employment, but lawful whistleblowing and protected rights remain protected.</p>\",\"owner\":\"HR / Payroll / IT / Operations\",\"policyIds\":[\"HR-ER-006\",\"IT-SC-002\",\"CO-HP-007\",\"CO-HP-101\"],\"formIds\":[\"HR-FM-055\",\"HR-FM-056\",\"HR-FM-057\",\"HR-FM-058\",\"IT-FM-002\"],\"externalAuthorities\":[\"CA-PAY\"],\"employeeAction\":\"\"},{\"id\":\"acknowledgment\",\"order\":48,\"number\":\"48\",\"eyebrow\":\"SIGNATURE\",\"title\":\"Employee acknowledgment and receipt\",\"lead\":\"The acknowledgment confirms receipt of a specific controlled version; it is not an agreement to waive rights.\",\"bodyHtml\":\"<p>I acknowledge that I received access to the Care Indeed Employee & Field Workforce Handbook identified below. I understand that I am responsible for reading it, asking questions, and following applicable current policies. I understand that this handbook is a summary, is not a contract, does not guarantee employment for any period, and does not alter at-will employment. I understand that applicable law, current controlled policies, job descriptions, wage notices, and benefit plan documents may provide additional or different rights and obligations.</p><p>I understand that I may report concerns or exercise protected rights without retaliation, and that nothing in this acknowledgment waives rights under federal, California, or local law.</p><div class=\\\"table-wrap\\\"><table class=\\\"data-table\\\"><thead><tr><th>Field</th><th>Employee entry</th></tr></thead><tbody><tr><td>Handbook ID / version</td><td>CI-HR-HB-2026 / ______</td></tr><tr><td>Effective date</td><td>________________</td></tr><tr><td>Employee printed name</td><td>________________</td></tr><tr><td>Employee ID</td><td>________________</td></tr><tr><td>Primary role / location</td><td>________________</td></tr><tr><td>Language / accessible format received</td><td>________________</td></tr><tr><td>Signature</td><td>________________</td></tr><tr><td>Date</td><td>________________</td></tr></tbody></table></div><aside class=\\\"callout info\\\"><strong>Electronic acknowledgment</strong><div>When implemented in the employee portal, the record should bind the employee, handbook version, effective date, content hash, language, acknowledgment text, date/time, and authenticated actor.</div></aside>\",\"owner\":\"HR\",\"policyIds\":[\"GV-PM-003\",\"EN-LC-001\",\"EN-LC-003\"],\"formIds\":[\"EN-FM-001\"],\"externalAuthorities\":[],\"employeeAction\":\"\"}]") as HandbookSection[];

export function getHandbookSection(id: string): HandbookSection | undefined {
  return HANDBOOK_SECTIONS.find((s) => s.id === id);
}
